This pattern is duplicated from the getChunk function. Consider extracting this logic into a helper function to reduce code duplication.
```suggestion
// Helper function to invoke gRPC methods and return 'chunks' from the response
function invokeAndGetChunks(method, data) {
    let response;
    group('internal', function () {
        client.connect('commondataserver:5000', {
            plaintext : true
        });
        response = client.invoke(method, data);
        check(response, {
            'status is OK' : (r) => r && r.status === grpc.StatusOK,
        });
        client.close();
    });
    if (response.message && response.message.hasOwnProperty('chunks')) {
        return response.message['chunks'];
    } else {
        return [];
    }
}

export function getChunk(source, size) {
    const data = {
        "source" : source,
        "size"   : size
    };
    return invokeAndGetChunks('element.DataService/getData', data);
}

export function addChunk(source, chunks) {
    const data = {
        "source" : source,
        "chunks" : chunks
    };
    return invokeAndGetChunks('element.DataService/addData', data);
```

